110	func postRoom(t *testing.T, baseURL, body string) (int, map[string]any) {
111		t.Helper()
112		resp, err := httpClient.Post(baseURL+"/api/rooms", "application/json", strings.NewReader(body))
113		if err != nil {
114			t.Fatalf("POST /api/rooms 失败: %v", err)
115		}
116		defer resp.Body.Close()
117		payload, err := io.ReadAll(resp.Body)
118		if err != nil {
119			t.Fatalf("读取响应失败: %v", err)
120		}
